// The F&O Show - Maps in X++
// A small class used as a VALUE inside a Map in part 9.
class MyMapProduct
{
    str  itemId;
    str  name;
    real price;

}

Method.Source:
public static MyMapProduct construct(str _itemId, str _name, real _price)
{
    MyMapProduct product = new MyMapProduct();

    product.parmItemId(_itemId);
    product.parmName(_name);
    product.parmPrice(_price);

    return product;
}

public str parmItemId(str _itemId = itemId)
{
    itemId = _itemId;

    return itemId;
}

public str parmName(str _name = name)
{
    name = _name;

    return name;
}

public real parmPrice(real _price = price)
{
    price = _price;

    return price;
}
